test('backend acceptance register is valid JSON and workload baseline totals remain internally consistent',()=>{
 const register=JSON.parse(readFileSync(new URL('../backend-work.json',import.meta.url),'utf8')),baseline=JSON.parse(readFileSync(new URL('../backend-workload-baseline.json',import.meta.url),'utf8'));assert.equal(typeof register.next,'string');assert.equal(typeof register.nextBackendPriority,'string');assert.equal(baseline.frontendExcluded,true);assert.equal(baseline.isReleaseAcceptance,false);const total=baseline.groups.reduce((n:number,g:{totalPoints:number})=>n+g.totalPoints,0),done=baseline.groups.reduce((n:number,g:{completedPoints:number})=>n+g.completedPoints,0);assert.equal(total,baseline.reportedBaseline.totalPoints);assert.equal(done,baseline.reportedBaseline.completedPoints);assert.equal(total-done,baseline.reportedBaseline.remainingPoints);
});
